def perform_arithmetic(num1, num2, operator):
    """Performs the given arithmetic operation on two numbers."""

    # Handle invalid operators
    if operator not in ['+', '-', '*', '/']:
        raise ValueError("Invalid operator. Please use +, -, *, or /.")

    # Handle division by zero
    if operator == '/':
        if num2 == 0:
            raise ZeroDivisionError("Cannot divide by zero.")

    # Perform the operation
    if operator == '+':
        result = num1 + num2
    elif operator == '-':
        result = num1 - num2
    elif operator == '*':
        result = num1 * num2
    elif operator == '/':
        result = num1 / num2

    return result

# Get user input
